def copy_subject_satellite_data(apps, schema_editor):
    NSP = apps.get_model("catalogs", "NameSubjectProfile")
    Contact = apps.get_model("catalogs", "SubjectContactProfile")
    Address = apps.get_model("catalogs", "SubjectAddressProfile")
    Yard = apps.get_model("catalogs", "SubjectYardSettings")
    Zpo = apps.get_model("catalogs", "SubjectZpoSettings")
    Pio = apps.get_model("catalogs", "SubjectPioProfile")

    for row in NSP.objects.all().iterator():
        Contact.objects.create(
            subject_id=row.pk,
            contact_phone=row.contact_phone or "",
            contact_note=row.contact_note or "",
        )
        Address.objects.create(
            subject_id=row.pk,
            facility_address_id=row.facility_address_id,
            fulfillment_address_id=row.fulfillment_address_id,
            facility_latitude=row.facility_latitude,
            facility_longitude=row.facility_longitude,
            fulfillment_latitude=row.fulfillment_latitude,
            fulfillment_longitude=row.fulfillment_longitude,
            fulfillment_orp=row.fulfillment_orp or "",
            fulfillment_iczuj=row.fulfillment_iczuj or "",
        )
        Yard.objects.create(
            subject_id=row.pk,
            is_collection_yard=row.is_collection_yard,
            yard_allow_pruvodka=row.yard_allow_pruvodka,
            yard_allow_matrix=row.yard_allow_matrix,
            yard_svoz_dispatch_group=row.yard_svoz_dispatch_group or "",
        )
        Zpo.objects.create(
            subject_id=row.pk,
            system_generates_zpo=row.system_generates_zpo,
        )
        Pio.objects.create(
            subject_id=row.pk,
            pio_officer_name=row.pio_officer_name or "",
            pio_officer_phone=row.pio_officer_phone or "",
            pio_officer_email=row.pio_officer_email or "",
            pio_waste_type_id=row.pio_waste_type_id,
            pio_suffix_id=row.pio_suffix_id,
            pio_outside_map_lat=row.pio_outside_map_lat,
            pio_outside_map_lng=row.pio_outside_map_lng,
            pio_outside_map_orp=row.pio_outside_map_orp or "",
            pio_outside_map_iczuj=row.pio_outside_map_iczuj or "",
        )


